import type { Source } from "./Core";
/**
 * Callbag sink that consume both pullable and listenable sources. When called
 * on a pullable source, it will iterate through its data. When called on a
 * listenable source, it will observe its data.
 *
 * Adapted from https://github.com/staltz/callbag-for-each
 *
 * @param proc A function that receives an item of data from the source.
 *
 * @internal
 */
export declare const forEach: <T>(proc: (item: T) => void) => (source: Source<T, unknown>) => void;
